#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

int main(void){
    int N, K;
    long long T;
    if (scanf("%d %d %lld", &N, &K, &T) != 3) return 0;
    static int P[305], G[305], pre[305];
    for (int i = 1; i <= N; i++) scanf("%d", &P[i]);
    for (int i = 1; i <= N; i++) scanf("%d", &G[i]);
    pre[0] = 0;
    for (int i = 1; i <= N; i++) pre[i] = pre[i-1] + G[i];

    int k = K;
    /* minimo de trocas para qualquer configuracao alvo <= K*(N-K)
       (cada troca util faz um membro cruzar um nao-membro, no maximo uma vez) */
    long long lim = (long long)k * (long long)(N - k);
    int cap = (int)(T < lim ? T : lim);
    int VS = 9 * k + 1;
    int FS = 2 * k + 1;
    size_t tot = (size_t)FS * (size_t)VS;

    uint16_t *cur = (uint16_t*)malloc(tot * sizeof(uint16_t));
    uint16_t *nxt = (uint16_t*)malloc(tot * sizeof(uint16_t));
    if (!cur || !nxt) return 1;
    memset(cur, 0xFF, tot * sizeof(uint16_t));       /* 65535 = "inalcançavel" */
    cur[(size_t)k * VS] = 0;                          /* F=0, valor 0, custo 0 */

    /* DP varrendo posicoes; estado F = (membros em prefixo) - (alvos em prefixo).
       Custo parcial = soma de |F_b| nas fronteiras = EMD = soma |s_j - t_j|.
       Valor = soma dos P nos pratos escolhidos como alvos. */
    for (int i = 1; i <= N; i++){
        int m = G[i], p = P[i];
        int ap = pre[i-1], ac = pre[i];
        int lo = ac - k, hi = ac;
        int wc = (i < N);
        int im1 = i - 1;
        for (int f = lo; f <= hi; f++)
            memset(nxt + (size_t)(f + k) * VS, 0xFF, (size_t)VS * sizeof(uint16_t));
        for (int f = ap - k; f <= ap; f++){
            const uint16_t *pr = cur + (size_t)(f + k) * VS;
            int B = ap - f;                            /* alvos ja escolhidos */
            int vmax = 9 * (B < im1 ? B : im1);        /* valor <= 9*B, B <= i-1 */
            int f1 = f + m, f2 = f1 - 1;
            int ok0 = (f1 >= lo && f1 <= hi);
            int ok1 = (f2 >= lo && f2 <= hi);
            uint16_t *r0 = ok0 ? nxt + (size_t)(f1 + k) * VS : NULL;
            uint16_t *r1 = ok1 ? nxt + (size_t)(f2 + k) * VS : NULL;
            int w0 = 0, w1 = 0;
            if (wc){
                if (ok0) w0 = f1 < 0 ? -f1 : f1;
                if (ok1) w1 = f2 < 0 ? -f2 : f2;
            }
            for (int v = 0; v <= vmax; v++){
                unsigned c = pr[v];
                if (c > cap) continue;
                if (ok0){                              /* posicao i nao e alvo */
                    unsigned nc = c + w0;
                    if (nc <= cap && nc < r0[v]) r0[v] = (uint16_t)nc;
                }
                if (ok1){                              /* posicao i e alvo */
                    unsigned nc = c + w1;
                    int v2 = v + p;
                    if (nc <= cap && nc < r1[v2]) r1[v2] = (uint16_t)nc;
                }
            }
        }
        uint16_t *tmp = cur; cur = nxt; nxt = tmp;
    }

    int ans = 0;
    const uint16_t *fr = cur + (size_t)k * VS;        /* F = 0 no final */
    for (int v = VS - 1; v >= 0; v--)
        if (fr[v] != 0xFFFF){ ans = v; break; }
    printf("%d\n", ans);
    free(cur); free(nxt);
    return 0;
}
